import "model.cod" Node;
using "model.cod" Weighted;
data Node <: Weighted;
function create(arena::region)::ref<Node> { alloc arena Node(7) }
export create;

sources.entry.cod:
using symbol "std:io" @print;
using "first.cod" create as first;
using "next.cod" create as next;
symbol @arena::region;
effect @arena <- region(4096u64);
{
 let node = fold (i in 0u32 .. 3u32, node = first(@arena)) { next(@arena) };
 behave @print(deref(node).value);
};

