type Entity;
type Weighted <: Entity;
type Alternate <: Entity;
data Leaf { value::i64; next::ref<Leaf>; }
data Box { item::ref<Leaf>; }
function rank(x::Entity)::i64 { 1 }
function rank(x::Weighted)::i64 { 2 }
export Entity; export Weighted; export Alternate; export Leaf; export Box; export rank;

sources.first.cod:
import "model.cod" Leaf;
using "model.cod" Box;
using "model.cod" Weighted;
data Leaf <: Weighted;
data PrivateMarker <: Weighted { ignored::i64; }
function create(arena::region)::ref<Box> {
 let leaf = alloc arena Leaf(3, null);
 setfield(leaf, next, leaf);
 alloc arena Box(leaf)
}
export create;

