sources.entry.cod:
using symbol "std:io" @print;
using "model.cod" rank;
using "first.cod" create as first;
using "next.cod" create as next;
symbol @arena::region;
effect @arena <- region(8192u64);
{
 let box = fold (i in 0u32 .. 3u32, current = first(@arena)) { next(@arena) };
 let leaf = deref(deref(box).item);
 behave @print(leaf.value);
 behave @print(rank(deref(leaf.next)));
};

